function reorderList(head) {
  if (!head || !head.next) return head;

  // 1. Find the middle of the list
  let slow = head;
  let fast = head;
  while (fast.next && fast.next.next) {
    slow = slow.next;
    fast = fast.next.next;
  }

  // 2. Reverse the second half
  let second = slow.next;
  slow.next = null;
  let prev = null;
  while (second) {
    const next = second.next;
    second.next = prev;
    prev = second;
    second = next;
  }
  let secondHead = prev;

  // 3. Merge the two halves, alternating nodes
  let first = head;
  while (secondHead) {
    const t1 = first.next;
    const t2 = secondHead.next;
    first.next = secondHead;
    secondHead.next = t1;
    first = t1;
    secondHead = t2;
  }

  return head;
}

