// Builds a list from pairs of [val, randomIndex] (randomIndex is null or an
// index into the same array, matching LeetCode's serialization for this problem).
function buildRandomList(pairs) {
  if (pairs.length === 0) return null;
  const nodes = pairs.map(([val]) => new Node(val));
  for (let i = 0; i < nodes.length; i++) {
    nodes[i].next = i + 1 < nodes.length ? nodes[i + 1] : null;
    const randIdx = pairs[i][1];
    nodes[i].random = randIdx === null || randIdx === undefined ? null : nodes[randIdx];
  }
  return nodes[0];
}

// Converts a list back into [val, randomIndex] pairs for comparison.
